const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Hong Kong
  const hongKong = ee.Geometry.Point([114.2, 22.3]);
  const region = hongKong.buffer(50000); // ~50 km buffer

  // 2. Define time periods
  const jan_start = '2020-01-01';
  const jan_end = '2020-01-20';
  const feb_start = '2020-02-10';
  const feb_end = '2020-02-25';

  // 3. Acquire TROPOMI NO2 data
  const s5p = ee.ImageCollection('COPERNICUS/S5P/NRTI_L3_NO2');

  const janCollection = s5p
    .filterBounds(region)
    .filterDate(jan_start, jan_end)
    .select('tropospheric_no2_column_number_density');

  const febCollection = s5p
    .filterBounds(region)
    .filterDate(feb_start, feb_end)
    .select('tropospheric_no2_column_number_density');

  // 4. Check collection sizes
  const janSize = janCollection.size().getInfo();
  const febSize = febCollection.size().getInfo();

  print(`January 1-20, 2020 Images: ${janSize}`);
  print(`February 10-25, 2020 Images: ${febSize}`);

  if (janSize === 0 || febSize === 0) {
    print('No valid data for one or both periods.');
    print('C1');
    return;
  }

  // 5. Calculate mean NO2 for each period
  const janMean = janCollection.mean();
  const febMean = febCollection.mean();

  // 6. Reduce to region and get mean values
  const janStats = janMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5600, // TROPOMI resolution
    maxPixels: 1e9
  }).getInfo();

  const febStats = febMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5600,
    maxPixels: 1e9
  }).getInfo();

  const janNO2 = janStats['tropospheric_no2_column_number_density'];
  const febNO2 = febStats['tropospheric_no2_column_number_density'];

  // 7. Validation
  if (janNO2 === null || janNO2 === undefined || isNaN(janNO2) ||
      febNO2 === null || febNO2 === undefined || isNaN(febNO2)) {
    print('Calculation resulted in invalid values.');
    print('C3');
    return;
  }

  // 8. Check for physically plausible values (NO2 in molecules/cm²)
  if (janNO2 < 0 || janNO2 > 5e16 || febNO2 < 0 || febNO2 > 5e16) {
    print('Values outside physically plausible range.');
    print('C3');
    return;
  }

  print(`January Mean NO2: ${janNO2.toExponential(2)} molecules/cm²`);
  print(`February Mean NO2: ${febNO2.toExponential(2)} molecules/cm²`);
  print(`Difference (Feb - Jan): ${(febNO2 - janNO2).toExponential(2)}`);
  print(`Percent Change: ${(((febNO2 - janNO2) / janNO2) * 100).toFixed(1)}%`);

  // 9. Determine answer
  if (febNO2 < janNO2) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
